-- Order of the practice-by-module list on each track page (the Skill Jar exam-prep path order).
-- A module is a submodule name; a course taught under several domains has the same position on each of its rows.
-- Generated by scripts/generate-submodule-seed-sql.ts. Additive: one nullable column, then fills empty positions only,
-- so positions the admin has set are never overwritten. Safe to re-run.

alter table quiz_submodules add column if not exists course_position integer;

with pos(track, title, position) as (values
  ($q$associate$q$, $q$Claude Platform & Model Foundations$q$, 1),
  ($q$associate$q$, $q$Prompting & Task Execution$q$, 2),
  ($q$associate$q$, $q$Evaluating & Validating Claude's Output$q$, 3),
  ($q$associate$q$, $q$Workflow Integration & Solution Design$q$, 4),
  ($q$associate$q$, $q$Configuration & Knowledge Management$q$, 5),
  ($q$associate$q$, $q$Governance, Risk & Responsible Use$q$, 6),
  ($q$associate$q$, $q$Troubleshooting & Optimization$q$, 7),
  ($q$developer$q$, $q$MSO Foundations$q$, 1),
  ($q$developer$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$, 2),
  ($q$developer$q$, $q$Claude Code, MCP & Integration$q$, 3),
  ($q$developer$q$, $q$Production Engineering, Evals & Security$q$, 4),
  ($q$developer$q$, $q$Accelerators & IP Contribution$q$, 5)
)
update quiz_submodules sm
set course_position = p.position
from pos p
join quiz_modules m on m.track = p.track
where sm.module_id = m.id and sm.title = p.title and sm.course_position is null;

-- Check: expect 12 module names, in this order, each with its position
select m.track, sm.title as module, min(sm.course_position) as position, count(*) as domain_rows
from quiz_submodules sm
join quiz_modules m on m.id = sm.module_id
group by m.track, sm.title
order by m.track, min(sm.course_position), sm.title;
